from collections import deque

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    result = []
    window = deque()
    k = 3

    for i, num in enumerate(numbers):
        while window and window[0] <= i - k:
            window.popleft()

        while window and numbers[window[-1]] < num:
            window.pop()

        window.append(i)

        if i >= k - 1:
            result.append(numbers[window[0]])

    return result

